<script setup lang="ts">
import {computed,inject,onBeforeUnmount,ref,watch} from 'vue';
import {RouterLink} from 'vue-router';
import {formatAmount} from '../../shared/formatAmount';
import {units4,decimal4} from './portalAmounts';
import ConsumptionPreview from './ConsumptionPreview.vue';
import PromoterIcon from './PromoterIcon.vue';
import {adminSessionKey} from './adminSession';
const session=inject(adminSessionKey);
const primary=computed(()=>session?.currentAdmin.value?.role==='ADMIN'&&session.currentAdmin.value.primary===true);
import {billingListGetApiV1AdminBillingConsumptions as list,billingDetailGetApiV1AdminBillingConsumptionsId as getDetail,type ResponseBillingApplicationLedgerAdminConsumptionQueryDetail as Detail} from './api';
const props=defineProps<{detail:Detail;recordId:string;balances:{before?:string|null;after?:string|null};previousId?:string;nextId?:string;busy:boolean}>();
const emit=defineEmits<{refresh:[]}>();
const item=computed(()=>props.detail.item!),task=computed(()=>props.detail.snapshot?.task),generation=computed(()=>props.detail.snapshot?.generation),enhancement=computed(()=>props.detail.snapshot?.enhancement);
const statuses:Record<string,string>={ROUTING:'准备中',CHARGE_PENDING:'扣费确认中',SUBMIT_PENDING:'提交中',RUNNING:'生成中',ARCHIVING:'保存结果中',REFUND_PENDING:'退款处理中',SUCCEEDED:'成功',PARTIAL_SUCCESS:'部分成功',FAILED:'失败',TIMED_OUT:'已超时',MISSING:'历史任务信息缺失',ARK_READY:'等待提交',ARK_SENDING:'提交确认中',ARK_RUNNING:'生成中',MPS_READY:'等待增强',MPS_SENDING:'增强提交确认中',MPS_RUNNING:'增强处理中',COMPLETE:'完成'};
const tone=(status?:string|null)=>status==='FAILED'||status==='TIMED_OUT'?'status-danger':['SUCCEEDED','COMPLETE'].includes(status||'')?'status-success':'status-pending';
const accounts:Record<string,string>={PERSONAL:'个人',ENTERPRISE:'企业',API:'API'};
const time=(value?:string|null)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'未记录';
const yuan=(value?:string|null)=>units4(value)===null?'—':formatAmount(value)+' 元';
function pointsYuan(value?:string|null){const p=units4(value),rate=units4(item.value.ledger?.rate4);return p===null||rate===null||rate<=0n?'—':yuan(decimal4(p*10000n/rate));}
const quantity=computed(()=>{const t=task.value;if(!t||t.id!==item.value.ledger?.taskId||t.type!==item.value.ledger?.type||t.model!==item.value.ledger?.model||!t.count||t.count<=0||t.type==='VIDEO'&&t.durationSeconds<=0)return null;return t.type==='VIDEO'?t.count*t.durationSeconds:t.type==='IMAGE'?t.count:null;});
const unitPrice=computed(()=>{const amount=units4(item.value.ledger?.amount4);return amount===null||!quantity.value?'—':formatAmount(decimal4(amount/BigInt(quantity.value)))+' 元/'+(task.value?.type==='VIDEO'?'秒':'张');});
const duration=(value?:number|null)=>value==null?'未记录':(value/60000).toFixed(2)+' 分钟';
const totalDuration=computed(()=>{if(generation.value?.durationMs==null||enhancement.value&&enhancement.value.durationMs==null)return null;return generation.value.durationMs+(enhancement.value?.durationMs||0);});
const stages=computed(()=>[{value:generation.value,original:true,label:generation.value?.provider?generation.value.provider+'生成':'生成信息'},...(enhancement.value?[{value:enhancement.value,original:false,label:(enhancement.value.provider||'供应商未记录')+'增强'}]:[])]);
function outputs(stage:typeof generation.value,original:boolean){const recorded=stage?.outputs||(original&&!enhancement.value?task.value?.results:[])||[];return [...new Set([...Array.from({length:task.value?.count||0},(_,i)=>i),...recorded.map(o=>o.index??0)])].sort((a,b)=>a-b).map(index=>({index,output:recorded.find(o=>o.index===index)}));}
const refundLabel=computed(()=>{const posted=(units4(item.value.ledger?.refundedPoints4)||0n)>0n;if(task.value?.refundStatus==='PENDING')return posted?'退款已入账，任务确认处理中':'退款处理中';if(posted)return '已退款';return task.value?.refundStatus==='COMPLETED'?'退款入账记录待核对':'';});
const finalOutputs=computed(()=>(task.value?.results||[]).filter(o=>o.fileId));
const outputIndex=ref(0),allAssets=ref(false),promptDialog=ref<HTMLDialogElement>(),copied=ref('');
async function copy(value:string|undefined|null,name:string){if(!value)return;try{await navigator.clipboard.writeText(value);copied.value=name;}catch{copied.value='failed';}}
function historyPlaceholder(record:Detail){const status=record.snapshot?.task?.status||record.item?.taskStatus||'';return status==='FAILED'?'生成失败':status==='TIMED_OUT'?'生成超时':status==='SUCCEEDED'||status==='PARTIAL_SUCCESS'?'暂无生成结果':statuses[status]||'暂无生成结果';}
const history=ref<Detail[]>([]),historyTotal=ref(0),historyError=ref(false),historyBusy=ref(false),historyPage=ref(1);
const historyPageSize=20,historyPages=computed(()=>Math.max(1,Math.ceil(historyTotal.value/historyPageSize)));
const historyPageButtons=computed(()=>[...new Set([1,historyPage.value-1,historyPage.value,historyPage.value+1,historyPages.value])].filter(n=>n>=1&&n<=historyPages.value).sort((a,b)=>a-b));
let version=0,historyCutoff='';
async function loadHistory(target=historyPage.value){
 const owner=item.value.ledger?.ownerId||item.value.user?.id;if(!owner)return;
 const own=++version;historyPage.value=target;historyError.value=false;historyBusy.value=true;history.value=[];
 try{
  const page=(await list({userId:owner,to:historyCutoff,offset:(target-1)*historyPageSize,limit:historyPageSize})).data;
  if(own!==version)return;
  const records=await Promise.all((page.items||[]).filter(r=>r.ledger?.id).map(async r=>{try{const data=(await getDetail(r.ledger!.id!)).data;return data.item?.ledger?.id===r.ledger!.id&&(data.item?.ledger?.ownerId||data.item?.user?.id)===owner?data:{item:r,entries:[],snapshot:null};}catch{return {item:r,entries:[],snapshot:null};}}));
  if(own===version){history.value=records;historyTotal.value=page.total;}
 }catch{if(own===version)historyError.value=true;}finally{if(own===version)historyBusy.value=false;}
}
watch(()=>props.recordId,()=>{outputIndex.value=0;copied.value='';allAssets.value=false;historyTotal.value=0;historyCutoff=new Date().toISOString();void loadHistory(1);},{immediate:true});onBeforeUnmount(()=>{version++;});
</script>
<template><div class="consumption-record-detail"><header class="consumption-detail-heading"><h1>消费记录详情</h1><span class="consumption-id">ID {{recordId}}</span><span class="status" :class="tone(item.taskStatus)">● {{statuses[item.taskStatus||'MISSING']||item.taskStatus}}</span><nav aria-label="记录切换"><RouterLink v-if="primary&&item.ledger?.taskId" :to="{path:'/admin/provider-logs',query:{taskId:item.ledger.taskId}}">查看生成日志</RouterLink><RouterLink v-if="previousId" :to="'/admin/consumption/'+encodeURIComponent(previousId)">‹ 上一条</RouterLink><button v-else disabled>‹ 上一条</button><RouterLink v-if="nextId" :to="'/admin/consumption/'+encodeURIComponent(nextId)">下一条 ›</RouterLink><button v-else disabled>下一条 ›</button><button type="button" aria-label="刷新详情" :disabled="busy" @click="emit('refresh')">↻</button><RouterLink to="/admin/consumption" aria-label="关闭消费详情">×</RouterLink></nav></header>
<div class="consumption-detail-grid"><div class="consumption-detail-left">
 <article class="consumption-panel consumption-basic"><h2>基本信息</h2><dl><dt>用户</dt><dd><RouterLink v-if="item.user?.id" :to="'/admin/users/'+encodeURIComponent(item.user.id)">{{item.user.nickname||'历史用户信息缺失'}}</RouterLink><span v-else>历史用户信息缺失</span><button class="consumption-copy" type="button" aria-label="复制用户 ID" @click="copy(item.user?.id,'user')"><PromoterIcon name="copy"/></button><small>{{item.user?.phone}}</small></dd><dt>公开任务 ID</dt><dd><code>{{item.ledger?.taskId}}</code><button class="consumption-copy" type="button" aria-label="复制公开任务 ID" @click="copy(item.ledger?.taskId,'task')"><PromoterIcon name="copy"/></button></dd><dt>时间</dt><dd>{{time(item.ledger?.createdAt)}}</dd><dt>类型</dt><dd><span class="consumption-type" :class="item.ledger?.type==='IMAGE'?'image':'video'">{{item.ledger?.type==='VIDEO'?'视频':item.ledger?.type==='IMAGE'?'图片':'—'}}</span></dd><dt>模型</dt><dd>{{item.modelName||item.ledger?.model||'—'}}</dd><dt>账户</dt><dd>当前 {{accounts[item.currentAccountType||'']||'未记录'}} · 消费时 {{accounts[item.ledger?.accountType||'']||'未记录'}}</dd><template v-if="task"><dt>规格</dt><dd>{{task.referenceFollowsFirstFrame?'跟随首帧':task.aspectRatio}} · {{task.resolution||'—'}}</dd></template></dl></article>
 <article class="consumption-panel consumption-cost" aria-label="消费金额"><h2>费用明细</h2><div class="consumption-cost-grid"><dl><dt>单价</dt><dd>{{unitPrice}}</dd><dt>{{task?.type==='VIDEO'?'时长':'数量'}}</dt><dd>{{quantity==null?'—':quantity+(task?.type==='VIDEO'?' 秒':' 张')}}</dd><dt>金额</dt><dd>{{yuan(item.ledger?.amount4)}}</dd></dl><div class="consumption-cost-balances"><p>消耗前余额：<strong>{{pointsYuan(balances.before)}}</strong></p><p>消耗金额：<strong>{{yuan(item.ledger?.amount4)}}</strong></p><p>消耗后余额：<strong>{{pointsYuan(balances.after)}}</strong></p></div></div><span v-if="refundLabel" class="status">{{refundLabel}}</span><p v-if="(units4(item.ledger?.refundedPoints4)||0n)>0n">退回金额：{{pointsYuan(item.ledger?.refundedPoints4)}}</p></article>
 <article v-if="task" class="consumption-panel consumption-chain"><header><h2>模型调用链</h2><span>总耗时 {{duration(totalDuration)}}</span></header><ol><li v-for="(stage,i) in stages" :key="i"><span class="chain-icon" :class="i?'enhancement':''"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M6 19a5 5 0 0 1-.8-9.94A7 7 0 0 1 18.75 8a5.5 5.5 0 0 1-.25 11H6Z"/></svg></span><article class="consumption-diagnostic" :aria-label="stage.original?'生成信息':'增强信息'"><header><h3>{{stage.label}}</h3><span class="status" :class="tone(stage.value?.status||task.status)">● {{statuses[stage.value?.status||task.status||'']||'未记录'}}</span></header><dl><div><dt>{{stage.original?(stage.value?.provider==='火山'?'火山任务 ID':'供应商任务 ID'):'增强任务 ID'}}</dt><dd><code>{{stage.value?.taskId||'未记录'}}</code><button v-if="stage.value?.taskId" class="consumption-copy" type="button" :aria-label="'复制'+stage.label+'任务 ID'" @click="copy(stage.value.taskId,'stage'+i)"><PromoterIcon name="copy"/></button></dd></div><div><dt>{{stage.original?'原生分辨率':'模板分辨率'}}</dt><dd>{{stage.value?.resolution||'未记录'}}</dd></div><div><dt>{{stage.original&&stage.value?.provider==='火山'?'火山生成耗时':stage.original?'生成耗时':'增强处理耗时'}}</dt><dd>{{duration(stage.value?.durationMs)}}</dd></div><div v-if="stage.original&&task.type==='VIDEO'"><dt>原生视频消耗 Token</dt><dd>{{stage.value?.videoTokens??'未记录'}}</dd></div><template v-if="!stage.original"><div><dt>编排 Schedule ID</dt><dd>{{stage.value?.scheduleId||'未记录'}}</dd></div><div v-if="!stage.value?.steps?.length"><dt>模板 Definition ID</dt><dd>{{stage.value?.definitionId??'未记录'}}</dd></div></template></dl><p v-if="stage.value?.failureCode" class="consumption-stage-error" role="status">失败阶段：{{stage.value.failureStage||'未记录'}} · {{stage.value.failureCode}}</p><div v-if="!stage.original&&stage.value?.steps?.length" class="consumption-result-list"><section v-for="step in stage.value.steps" :key="step.index" class="consumption-result-row" :aria-label="'增强步骤 '+(step.index+1)"><h4>步骤 {{step.index+1}}{{step.index===stage.value.steps.length-1?' · 最终输出':''}}</h4><dl><div><dt>输出分辨率</dt><dd>{{step.width>0&&step.height>0?step.width+' × '+step.height:'未记录'}}</dd></div><div><dt>节点处理耗时</dt><dd>{{duration(step.durationMs)}}</dd></div><div><dt>模板 Definition ID</dt><dd>{{step.definitionId}}</dd></div><div><dt>状态</dt><dd>{{statuses[step.status||'']||step.status||'未记录'}}</dd></div></dl><ConsumptionPreview v-if="step.fileId" :record-id="recordId" :file-id="step.fileId" video :label="'步骤 '+(step.index+1)+' 输出'"/><p v-else>步骤 {{step.index+1}} · 尚无可访问的文件记录{{step.failureCode?' · '+step.failureCode:''}}</p></section></div><div v-else class="consumption-result-list"><div v-for="entry in outputs(stage.value,stage.original)" :key="entry.index" class="consumption-result-row"><ConsumptionPreview v-if="entry.output?.fileId" :record-id="recordId" :file-id="entry.output.fileId" :video="task.type==='VIDEO'" :label="(stage.original?'原始输出 ':'增强输出 ')+(entry.index+1)"/><p v-else>{{stage.original?'原始输出':'增强输出'}} {{entry.index+1}} · 尚无可访问的文件记录</p></div></div></article></li></ol></article>
 <details class="consumption-panel consumption-ledger"><summary>扣费与退款账本</summary><div class="table-wrap"><table><thead><tr><th>时间</th><th>变动类型</th><th>积分变动</th><th>变动前积分</th><th>变动后积分</th><th>请求标识</th></tr></thead><tbody><tr v-for="entry in detail.entries" :key="entry.id||entry.requestId||''"><td>{{time(entry.createdAt)}}</td><td>{{entry.kind==='CONSUME'?'扣费':'退款'}}</td><td>{{formatAmount(entry.points4)}}</td><td>{{formatAmount(entry.balanceBefore4)}}</td><td>{{formatAmount(entry.balanceAfter4)}}</td><td><code>{{entry.requestId}}</code></td></tr></tbody></table></div></details>
</div><div class="consumption-detail-right"><template v-if="task">
 <article class="consumption-panel consumption-prompt-panel"><header><h2>提示词（Prompt）</h2><div><button type="button" @click="promptDialog?.showModal()">⛶ 点击查看所有</button><button type="button" @click="copy(task.prompt,'prompt')">{{copied==='prompt'?'已复制':'复制提示词'}}</button></div></header><p class="consumption-prompt">{{task.prompt||'—'}}</p><p v-if="task.failureMessage" class="consumption-stage-error">{{task.failureMessage}}</p></article>
 <article class="consumption-panel consumption-references"><header><h2>参考素材（{{detail.snapshot?.references?.length||0}} 项）</h2><button v-if="(detail.snapshot?.references?.length||0)>3" type="button" @click="allAssets=!allAssets">{{allAssets?'收起资产':'查看全部资产 ›'}}</button></header><div v-if="detail.snapshot?.references?.length" class="consumption-reference-list"><template v-for="reference in allAssets?detail.snapshot.references:detail.snapshot.references.slice(0,3)" :key="reference.index"><ConsumptionPreview v-if="reference.fileId" thumbnail :video="reference.kind==='VIDEO'" :audio="reference.kind==='AUDIO'" :record-id="recordId" :file-id="reference.fileId" :label="'参考素材 '+((reference.index||0)+1)"/><p v-else>参考素材 {{(reference.index||0)+1}} · 未保存可访问的文件记录</p></template></div><p v-else class="consumption-empty">暂无参考素材</p></article>
 <article class="consumption-panel consumption-final"><h2>{{task.type==='VIDEO'?'生成视频':'生成图片'}}（最终成品）</h2><div v-if="finalOutputs.length" class="consumption-final-grid"><ConsumptionPreview :key="finalOutputs[outputIndex]?.fileId||''" inline :record-id="recordId" :file-id="finalOutputs[outputIndex]!.fileId!" :video="task.type==='VIDEO'" :label="'最终成品 '+(outputIndex+1)"/><nav v-if="finalOutputs.length>1" aria-label="选择生成结果"><button v-for="(output,i) in finalOutputs" :key="output.index" type="button" :aria-pressed="outputIndex===i" @click="outputIndex=i">{{task.type==='VIDEO'?'视频':'图片'}} {{i+1}}</button></nav></div><p v-else class="consumption-empty">暂无最终成品</p></article>
</template><article v-else class="consumption-panel consumption-empty"><h2>历史任务信息缺失</h2></article>
 <article class="consumption-panel consumption-history" :aria-busy="historyBusy"><header><h2>历史生成（共 {{historyTotal}} 条）</h2><RouterLink :to="{path:'/admin/consumption',query:{userId:item.ledger?.ownerId||item.user?.id||undefined}}">查看该用户全部生成 ›</RouterLink></header><p v-if="historyError" role="alert">历史记录读取失败 <button type="button" @click="loadHistory()" :disabled="historyBusy">重试</button></p><div v-else class="consumption-history-list"><article v-for="record in history" :key="record.item?.ledger?.id||''"><ConsumptionPreview v-if="record.snapshot?.task?.results?.find(o=>o.fileId)?.fileId" thumbnail :video="record.snapshot.task.type==='VIDEO'" :record-id="record.item!.ledger!.id!" :file-id="record.snapshot.task.results!.find(o=>o.fileId)!.fileId!" :label="'历史生成 '+time(record.item?.ledger?.createdAt)"/><div v-else class="consumption-thumbnail consumption-history-placeholder">{{historyPlaceholder(record)}}</div><RouterLink :to="'/admin/consumption/'+encodeURIComponent(record.item?.ledger?.id||'')"><span>{{time(record.item?.ledger?.createdAt)}}</span><span>{{record.item?.modelName||record.item?.ledger?.model||'—'}} {{record.snapshot?.task?.resolution}}</span><strong>{{yuan(record.item?.ledger?.amount4)}}</strong></RouterLink></article><p v-if="!history.length&&!historyBusy" class="consumption-empty">暂无历史记录</p></div>
 <nav v-if="historyTotal>historyPageSize" class="consumption-pagination consumption-history-pagination" aria-label="历史生成分页"><span>{{historyPage}} / {{historyPages}} 页</span><div><button type="button" aria-label="历史生成上一页" :disabled="historyBusy||historyPage===1" @click="loadHistory(historyPage-1)">‹</button><button v-for="n in historyPageButtons" :key="n" type="button" :aria-current="historyPage===n?'page':undefined" :disabled="historyBusy" @click="loadHistory(n)">{{n}}</button><button type="button" aria-label="历史生成下一页" :disabled="historyBusy||historyPage>=historyPages" @click="loadHistory(historyPage+1)">›</button></div></nav></article>
</div></div><dialog ref="promptDialog" class="consumption-prompt-dialog" aria-label="完整提示词"><header><h2>提示词</h2><button type="button" aria-label="关闭完整提示词" @click="promptDialog?.close()">×</button></header><p>{{task?.prompt||'—'}}</p></dialog></div></template>
